  "events": [
    {
      "id": "wycliffe-gordon-welcome-to-georgia-town-jalc-new-york-2026-10-09",
      "artist": "Wycliffe Gordon",
      "subtitle": "Welcome to Georgia Town",
      "dates": {"start": "2026-10-09", "end": "2026-10-10"},
      "showtimes": ["16:30", "19:00", "21:00"],
      "venue": {"id": "appel-room-jazz-at-lincoln-center-new-york-ny", "name": "The Appel Room, Frederick P. Rose Hall", "city": "New York", "state": "NY", "country": "US"},
      "geographic_domain": "us_corridor",
      "status": "considering",
      "priority": "A",
      "category": "Autobiographical jazz program / septet and vocal chorus",
      "genres": ["Jazz", "Gospel", "American roots"],
