      },
      "sources": [
        {
          "url": "https://jazz.org/concert/wycliffe-gordon-welcome-to-georgia-town/",
          "publisher": "Jazz at Lincoln Center",
          "checked_on": "2026-08-28",
          "note": "Primary event page verifying the October 9-10 dates, all four showtimes, The Appel Room, the autobiographical program, Wycliffe Gordon Septet, and Damien Sneed & Friends chorus."
        },
        {
          "url": "https://wycliffegordon.com/gigs/",
          "publisher": "Wycliffe Gordon",
